#include <vector>
#include <unordered_map>
using namespace std;

class Solution {
public:
    vector<int> restoreArray(vector<vector<int>>& adjacentPairs) {
        unordered_map<int, vector<int>> adj;
        for (const auto& p : adjacentPairs) {
            adj[p[0]].push_back(p[1]);
            adj[p[1]].push_back(p[0]);
        }
        int start = 0;
        for (const auto& [node, neighbors] : adj) {
            if (neighbors.size() == 1) {
                start = node;
                break;
            }
        }
        int n = adjacentPairs.size() + 1;
        vector<int> res;
        res.reserve(n);
        res.push_back(start);
        int prev = 1e9 + 7;
        int curr = start;
        for (int i = 0; i < n - 1; ++i) {
            int nxt = (adj[curr][0] != prev) ? adj[curr][0] : adj[curr][1];
            res.push_back(nxt);
            prev = curr;
            curr = nxt;
        }
        return res;
    }
};

import java.util.*;

class Solution {
    public int[] restoreArray(int[][] adjacentPairs) {
        Map<Integer, List<Integer>> adj = new HashMap<>();
        for (int[] p : adjacentPairs) {
            adj.computeIfAbsent(p[0], k -> new ArrayList<>()).add(p[1]);
            adj.computeIfAbsent(p[1], k -> new ArrayList<>()).add(p[0]);
        }
        int start = 0;
        for (Map.Entry<Integer, List<Integer>> entry : adj.entrySet()) {
            if (entry.getValue().size() == 1) {
                start = entry.getKey();
                break;
            }
        }
        int n = adjacentPairs.length + 1;
        int[] res = new int[n];
        res[0] = start;
        int prev = Integer.MAX_VALUE;
        int curr = start;
        for (int i = 0; i < n - 1; ++i) {
            List<Integer> neighbors = adj.get(curr);
            int nxt = (neighbors.get(0) != prev) ? neighbors.get(0) : neighbors.get(1);
            res[i + 1] = nxt;
            prev = curr;
            curr = nxt;
        }
        return res;
    }
}

/**
 * @param {number[][]} adjacentPairs
 * @return {number[]}
 */
var restoreArray = function(adjacentPairs) {
    const adj = new Map();
    for (const [u, v] of adjacentPairs) {
        if (!adj.has(u)) adj.set(u, []);
        if (!adj.has(v)) adj.set(v, []);
        adj.get(u).push(v);
        adj.get(v).push(u);
    }
    let start = null;
    for (const [node, neighbors] of adj) {
        if (neighbors.length === 1) {
            start = node;
            break;
        }
    }
    const n = adjacentPairs.length + 1;
    const res = [start];
    let prev = null;
    let curr = start;
    for (let i = 0; i < n - 1; ++i) {
        const neighbors = adj.get(curr);
        const nxt = neighbors[0] !== prev ? neighbors[0] : neighbors[1];
        res.push(nxt);
        prev = curr;
        curr = nxt;
    }
    return res;
};
